<script>
// ── FHIR extension & profile URL constants ─────────────────────────────────
const CHANGE_PROFILE =
  "http://ihris.org/fhir/StructureDefinition/position-change-reason-profile";

const EXT = {
  POSITION: "http://ihris.org/fhir/StructureDefinition/position-reference",
  EMP_CAT: "http://ihris.org/fhir/StructureDefinition/employment-category",
  POS_NAME: "http://ihris.org/fhir/StructureDefinition/ihris-basic-name",
  NOTCH: "http://ihris.org/fhir/StructureDefinition/notch",
  DEPARTMENT: "http://ihris.org/fhir/StructureDefinition/department",
  DESIGNATION: "http://ihris.org/fhir/StructureDefinition/designation",
  CHANGE_REASON: "http://ihris.org/fhir/StructureDefinition/change-reason",
  PREV_POSITION: "http://ihris.org/fhir/StructureDefinition/previous-position",
  CHANGE_DATE: "http://ihris.org/fhir/StructureDefinition/change-date",
};

// Cache resolved Location names to avoid re-fetching same facility/council/district
const _locationCache = {};
async function fetchLocation(ref) {
  if (_locationCache[ref]) return _locationCache[ref];
  const res = await fetch(`/fhir/${ref}`);
  const data = await res.json();
  _locationCache[ref] = data;
  return data;
}

export default {
  name: "PositionHistory",

  props: {
    queries: {
      type: Object,
      required: true,
      // queries.practitioner → Practitioner FHIR id (no prefix)
    },
  },

  data() {
    return {
      loading: false,
      error: null,
      practitionerName: "",

      // Enriched positions, newest first.  active roles sort to top.
      positions: [],

      changeHeaders: [
        {
          text: "Previous Position",
          value: "previousPosition",
          sortable: false,
        },
        { text: "Change Reason", value: "reason", sortable: false },
        { text: "Date", value: "date", sortable: false, width: 130 },
      ],
    };
  },

  computed: {
    initials() {
      return this.getInitials(this.practitionerName);
    },
    activePosition() {
      return this.positions.find((p) => p.active) || null;
    },
    activeCount() {
      return this.positions.filter((p) => p.active).length;
    },
  },

  async mounted() {
    await this.loadAll();
  },

  methods: {
    // ── Top-level orchestration ───────────────────────────────────────────
    async loadAll() {
      this.loading = true;
      this.error = null;
      try {
        await this.loadPractitioner();
        await this.loadAllRoles();
      } catch (err) {
        console.error("PositionHistory loadAll error", err);
        this.error = "Failed to load position history. Please try again.";
      } finally {
        this.loading = false;
      }
    },

    // ── Practitioner name ─────────────────────────────────────────────────
    async loadPractitioner() {
      try {
        const res = await fetch(
          `/fhir/Practitioner/${this.queries.practitioner}`,
        );
        const data = await res.json();
        this.practitionerName = this.parsePractitionerName(data);
      } catch (_) {
        this.practitionerName = `Practitioner/${this.queries.practitioner}`;
      }
    },

    // ── Fetch all PractitionerRole records for this practitioner ──────────
    async loadAllRoles() {
      const res = await fetch(
        `/fhir/PractitionerRole?practitioner=Practitioner/${this.queries.practitioner}&_count=100&_sort=-date`,
      );
      const data = await res.json();
      const entries = (data.entry || []).map((e) => e.resource);

      if (!entries.length) {
        this.positions = [];
        return;
      }

      // Enrich all roles in parallel — location cache prevents duplicate fetches
      const enriched = await Promise.all(
        entries.map((r) => this.enrichRole(r)),
      );

      // Active roles first, then sorted newest start date first within each group
      enriched.sort((a, b) => {
        if (a.active !== b.active) return a.active ? -1 : 1;
        return (b.startDate || "").localeCompare(a.startDate || "");
      });

      // Auto-expand the first (current/most recent) position
      if (enriched.length > 0) {
        enriched[0].expanded = true;
        await this.loadBasicRecords(enriched[0]);
      }

      this.positions = enriched;
    },

    // ── Enrich a single PractitionerRole resource ─────────────────────────
    async enrichRole(data) {
      const pos = {
        roleId: data.id,
        expanded: false,
        positionChanges: null,

        active: data.active !== false,
        startDate: data.period?.start || null,
        endDate: data.period?.end || null,
        designation: "",
        department: "",
        facility: "",
        council: "",
        district: "",
        employmentCategory: "",
      };

      // Employment category
      const empCat = this.getExt(data, EXT.EMP_CAT, "valueCoding");
      pos.employmentCategory = empCat?.display || empCat?.code || "";

      // All secondary fetches in parallel
      const promises = [];

      // Facility hierarchy from role.location[0]
      const facilityRef = data.location?.[0]?.reference;
      if (facilityRef) {
        promises.push(this.loadFacilityHierarchy(facilityRef, pos));
      }

      // Position Basic → designation + department
      const posRef = this.getExt(data, EXT.POSITION, "valueReference");
      if (posRef?.reference) {
        const posId = posRef.reference.split("/")[1];
        promises.push(
          fetch(`/fhir/Basic/${posId}`)
            .then((r) => r.json())
            .then((d) => this.enrichPositionFields(d, pos))
            .catch(() => {
              pos.designation = posRef.display || posRef.reference;
            }),
        );
      }

      await Promise.all(promises);
      return pos;
    },

    // ── Facility → Council → District chain ──────────────────────────────
    async loadFacilityHierarchy(facilityRef, pos) {
      try {
        const facData = await fetchLocation(facilityRef);
        pos.facility = facData.name || facilityRef;

        const councilRef = facData.partOf?.reference;
        if (councilRef) {
          const councilData = await fetchLocation(councilRef);
          pos.council = councilData.name || councilRef;

          const districtRef = councilData.partOf?.reference;
          if (districtRef) {
            const districtData = await fetchLocation(districtRef);
            pos.district = districtData.name || districtRef;
          }
        }
      } catch (_) {
        pos.facility = facilityRef;
      }
    },

    // ── Position Basic fields ─────────────────────────────────────────────
    async enrichPositionFields(posData, pos) {
      // Designation follows a valueReference to another Basic
      const desigRef = this.getExt(posData, EXT.DESIGNATION, "valueReference");
      if (desigRef?.reference) {
        try {
          const desigId = desigRef.reference.split("/")[1];
          const desigRes = await fetch(`/fhir/Basic/${desigId}`);
          const desigData = await desigRes.json();
          pos.designation =
            this.getExt(desigData, EXT.POS_NAME, "valueString") ||
            desigRef.display ||
            "";
        } catch (_) {
          pos.designation = desigRef.display || "";
        }
      }
      // Department
      const deptCoding = this.getExt(posData, EXT.DEPARTMENT, "valueCoding");
      pos.department = deptCoding?.display || deptCoding?.code || "";
    },

    // ── Lazy-load change reasons for one position ───────────────────
    async loadBasicRecords(pos) {
      if (pos.positionChanges !== null) return; // already loaded
      try {
        const res = await fetch(
          `/fhir/Basic?practitionerrole=PractitionerRole/${pos.roleId}&_count=100&_sort=-_lastUpdated`,
        );
        const data = await res.json();
        const entries = (data.entry || []).map((e) => e.resource);

        const changeResources = entries.filter((r) =>
          r.meta?.profile?.some((p) => p === CHANGE_PROFILE),
        );

        pos.positionChanges = await Promise.all(
          changeResources.map((r) => this.parseChangeReason(r)),
        );
      } catch (err) {
        console.error("loadBasicRecords error for role", pos.roleId, err);
        pos.positionChanges = [];
      }
    },

    // ── Change reason parser ──────────────────────────────────────────────
    async parseChangeReason(resource) {
      const entry = {
        id: resource.id,
        previousPosition: "",
        reason: "",
        date:
          this.getExt(resource, EXT.CHANGE_DATE, "valueDate") ||
          this.getExt(resource, EXT.CHANGE_DATE, "valueDateTime") ||
          null,
      };
      const reasonCoding = this.getExt(
        resource,
        EXT.CHANGE_REASON,
        "valueCoding",
      );
      entry.reason = reasonCoding?.display || reasonCoding?.code || "";
      const prevPosRef = this.getExt(
        resource,
        EXT.PREV_POSITION,
        "valueReference",
      );
      if (prevPosRef?.display) {
        entry.previousPosition = prevPosRef.display;
      } else if (prevPosRef?.reference) {
        try {
          const posId = prevPosRef.reference.split("/")[1];
          const posRes = await fetch(`/fhir/Basic/${posId}`);
          const posData = await posRes.json();
          const desigRef = this.getExt(
            posData,
            EXT.DESIGNATION,
            "valueReference",
          );
          if (desigRef?.reference) {
            const desigId = desigRef.reference.split("/")[1];
            const desigRes = await fetch(`/fhir/Basic/${desigId}`);
            const desigData = await desigRes.json();
            entry.previousPosition =
              this.getExt(desigData, EXT.POS_NAME, "valueString") ||
              desigRef.display ||
              prevPosRef.reference;
          } else {
            entry.previousPosition =
              this.getExt(posData, EXT.POS_NAME, "valueString") ||
              prevPosRef.reference;
          }
        } catch (_) {
          entry.previousPosition = prevPosRef.reference;
        }
      }
      return entry;
    },

    // ── Toggle expand / lazy-load ─────────────────────────────────────────
    async toggleExpand(pos) {
      pos.expanded = !pos.expanded;
      if (pos.expanded && pos.positionChanges === null) {
        await this.loadBasicRecords(pos);
      }
    },

    // ── Helpers ───────────────────────────────────────────────────────────
    getExt(resource, url, type) {
      const ext = resource?.extension?.find((e) => e.url === url);
      return ext ? ext[type] : null;
    },

    parsePractitionerName(resource) {
      if (!resource?.name?.length) return "";
      const n = resource.name[0];
      return ((n.given || []).join(" ") + " " + (n.family || "")).trim();
    },

    getInitials(name = "") {
      return name
        .split(" ")
        .filter(Boolean)
        .slice(0, 2)
        .map((w) => w[0].toUpperCase())
        .join("");
    },
  },
};
</script>

